// Product Events Analytics Pipeline

import { OlapTable, Stream, IngestApi, MaterializedView, Api, sql } from "@514labs/moose-lib";

// Data Model
export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: "view" | "cart" | "purchase";
  properties: {
    price?: number;
    page?: string;
  };
}

// 1. INGEST PIPELINE: OlapTable + Stream + IngestApi

// ClickHouse table for persistent storage
export const ProductEventsTable = new OlapTable<ProductEvent>("ProductEvents", {
  orderByFields: ["event_ts", "user_id", "product_id"],
});

// Redpanda stream buffer
export const ProductEventsStream = new Stream<ProductEvent>("ProductEvents", {
  destination: ProductEventsTable,
});

// HTTP ingest endpoint
export const ProductEventsIngest = new IngestApi<ProductEvent>("ProductEvents", {
  destination: ProductEventsStream,
});

// 2. MATERIALIZED VIEWS for pre-aggregations

// Top Products View (views/carts/purchases + revenue)
interface TopProductsRow {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const TopProductsMV = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["total_revenue"],
  selectStatement: sql.statement`
    SELECT
      product_id,
      sumIf(1, event_type = 'view') AS view_count,
      sumIf(1, event_type = 'cart') AS cart_count,
      sumIf(1, event_type = 'purchase') AS purchase_count,
      sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') AS total_revenue
    FROM ${ProductEventsTable}
    GROUP BY product_id
  `,
  selectTables: [ProductEventsTable],
});

// Conversion Funnel View
interface ConversionFunnelRow {
  step: string;
  unique_users: number;
  total_events: number;
}

export const ConversionFunnelMV = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["step"],
  selectStatement: sql.statement`
    SELECT
      event_type AS step,
      uniqExact(user_id) AS unique_users,
      count() AS total_events
    FROM ${ProductEventsTable}
    WHERE event_type IN ('view', 'cart', 'purchase')
    GROUP BY event_type
  `,
  selectTables: [ProductEventsTable],
});

// Hourly Activity View
interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
}

export const HourlyActivityMV = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql.statement`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ${ProductEventsTable}
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventsTable],
});

// 3. EGRESS APIs

// Top Products API
interface TopProductsInput {
  limit?: number;
}

export const topProductsApi = new Api<TopProductsInput, TopProductsRow[]>(
  "top-products",
  async ({ limit = 10 }, { client, sql }) => {
    const query = sql.statement`
      SELECT
        product_id,
        view_count,
        cart_count,
        purchase_count,
        total_revenue
      FROM ${TopProductsMV.targetTable}
      ORDER BY total_revenue DESC, purchase_count DESC
      LIMIT ${limit}
    `;
    const data = await client.query.execute<TopProductsRow>(query);
    return await data.json();
  }
);

// Conversion Funnel API
interface ConversionFunnelInput {}

export const conversionFunnelApi = new Api<ConversionFunnelInput, ConversionFunnelRow[]>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    const query = sql.statement`
      SELECT
        step,
        unique_users,
        total_events
      FROM ${ConversionFunnelMV.targetTable}
      ORDER BY
        CASE step
          WHEN 'view' THEN 1
          WHEN 'cart' THEN 2
          WHEN 'purchase' THEN 3
        END
    `;
    const data = await client.query.execute<ConversionFunnelRow>(query);
    return await data.json();
  }
);

// Hourly Activity API
interface HourlyActivityInput {
  hours?: number;
}

export const hourlyActivityApi = new Api<HourlyActivityInput, HourlyActivityRow[]>(
  "hourly-activity",
  async ({ hours = 24 }, { client, sql }) => {
    const query = sql.statement`
      SELECT
        hour,
        event_type,
        event_count
      FROM ${HourlyActivityMV.targetTable}
      WHERE hour >= now() - INTERVAL ${hours} HOUR
      ORDER BY hour DESC, event_type
    `;
    const data = await client.query.execute<HourlyActivityRow>(query);
    return await data.json();
  }
);

