### Streaming Data Ingest Setup (TypeScript)

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/olap/insert-data.mdx

Sets up a stream for ingesting data into an OLAP table using TypeScript. The `Stream.destination` is set to the `OlapTable`, enabling automatic batching and synchronization.

```typescript
import { Stream } from "@514labs/moose-lib";

interface Event {
    id: Key<string>;
    userId: string;
    timestamp: Date;
    eventType: string;
}

const eventsTable = new OlapTable<Event>("Events");

const stream = new Stream<Event>("Events", {
    destination: eventsTable // automatically syncs the stream to the table in ClickHouse-optimized batches
});
```

--------------------------------

### Define Ingestion API Schema and Destination

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/apis/ingest-api.mdx

Define the data model for ingestion and configure the destination stream and dead-letter queue. This example shows how to set up an IngestApi with a TypeScript interface and a Python Pydantic model.

```typescript
interface ExampleModel {
  id: string;
  userId: string;
  timestamp: Date;
  properties?: {
    device?: string;
    version?: number;
  }
}

export const api = new IngestApi<ExampleModel>("your-api-route", {
  destination: new Stream<ExampleModel>("your-stream-name"),
  deadLetterQueue: new DeadLetterQueue<ExampleModel>("your-dlq-name")
});
```

```python
from moose_lib import IngestPipeline, IngestPipelineConfig, IngestConfig
from pydantic import BaseModel

class Properties(BaseModel):
    device: Optional[str]
    version: Optional[int]

class ExampleModel(BaseModel):
    id: str
    userId: str
    timestamp: datetime
    properties: Properties

api = IngestApi[ExampleModel]("your-api-route", IngestConfig(
    destination=Stream[ExampleModel]("your-stream-name"),
    dead_letter_queue=DeadLetterQueue[ExampleModel]("your-dlq-name")
))
```

--------------------------------

### Configure Standalone Stream Components

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/streaming/create-stream.mdx

Manually define OlapTable, Stream, and IngestApi objects for granular control over the ingestion pipeline.

```typescript
interface RawData {
  id: string;
  value: number;
}
// Create a table for the raw data
export const rawTable = new OlapTable<RawData>("raw_data");

// Create a stream for the raw data
export const rawStream = new Stream<RawData>("raw_data", {
  destination: rawTable // Optional: Specify a destination table for the stream, sets up a process to sync data from the stream to the table
});

// Create an ingestion API for the raw data
export const rawIngestApi = new IngestApi<RawData>("raw_data", {
  destination: rawStream // Configure Moose to write all validated data to the stream
});
```

```python
from moose_lib import Stream, StreamConfig, Key, IngestApi, IngestConfig
from pydantic import BaseModel

class RawData(BaseModel):
    id: Key[str]
    value: int

raw_table = OlapTable[RawData]("raw_data")
raw_stream = Stream[RawData]("raw_data", StreamConfig(
  destination=raw_table # Optional: Specify a destination table for the stream, sets up a process to sync data from the stream to the table
))
raw_ingest_api = IngestApi[RawData]("raw_data", IngestConfig(
  destination=raw_stream # Configure Moose to write all validated data to the stream
))
```

--------------------------------

### Configure Standalone Components for Sync

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/streaming/sync-to-table.mdx

Manually configure standalone components like OlapTable, Stream, and IngestApi for more granular control over data syncing. Ensure the table is created before the stream, and the stream is set as the destination for the API.

```typescript
import { Stream, OlapTable, IngestApi, Key } from "@514labs/moose-lib";

interface Event {
  id: Key<string>;
  userId: string;
  timestamp: Date;
  eventType: string;
}

// Create table first
const eventsTable = new OlapTable<Event>("events");

// Create stream with destination table (enables auto-sync)
const eventsStream = new Stream<Event>("events", {
  destination: eventsTable  // This configures automatic batching
});

// Create API that writes to the stream
const eventsApi = new IngestApi<Event>("events", {
  destination: eventsStream
});

```

```python
from moose_lib import Stream, OlapTable, IngestApi, StreamConfig, Key
from pydantic import BaseModel
from datetime import datetime

class Event(BaseModel):
    id: Key[str]
    user_id: str
    timestamp: datetime
    event_type: str

# Create table first
events_table = OlapTable[Event]("events")

# Create stream with destination table (enables auto-sync)
events_stream = Stream[Event]("events", StreamConfig(
    destination=events_table  # This configures automatic batching
))

# Create API that writes to the stream
events_api = IngestApi[Event]("events", {
    "destination": events_stream
})

```

--------------------------------

### Define TypeScript Data Model with OlapTable

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/production-ready-analytics-agent/tutorial.mdx

Defines a data model for ClickHouse using `OlapTable`, specifying engine and ordering fields. Also shows how to define a `Stream` for data ingestion and an `IngestApi` for data processing.

```typescript
import { OlapTable, Stream, IngestApi, ClickHouseEngines } from "@514labs/moose-lib";

export const MyTable = new OlapTable<MyData>("my_table", {
  engine: ClickHouseEngines.MergeTree,
  orderByFields: ["low_cardinality_field", "timestamp"],
});

export const MyStream = new Stream<MyData>("my_data", {
  destination: MyTable,
});

export const MyIngestApi = new IngestApi<MyData>("my_data", {
  destination: MyStream,
});
```

